const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const b64 = '';
const payload = JSON.parse(zlib.brotliDecompressSync(Buffer.from(b64, 'base64')).toString('utf8'));
const files = payload.text || payload;
for (const [k, v] of Object.entries(files)) {
  fs.mkdirSync(path.dirname(k), { recursive: true });
  fs.writeFileSync(k, v, 'utf8');
}
if (payload.bin) {
  for (const [k, v] of Object.entries(payload.bin)) {
    fs.mkdirSync(path.dirname(k), { recursive: true });
    fs.writeFileSync(k, Buffer.from(v, 'base64'));
  }
}
console.log('Restored source and public training guide files.');
